# Zone-lane data embedded (lanes.db) as zlib+base64 CSV:  whid,pin,<6 zones>
LANES_B64 = """"""
LANES_KEYS = ['delhivery', 'bluedart_plus', 'dtdc', 'ekart', 'shadowfax', 'amazon']

def _data():
    return DATA_JSON

@lru_cache(maxsize=1)
def _load_lanes():
    text = zlib.decompress(base64.b64decode(LANES_B64)).decode("utf-8")
    lanes = {}
    for row in csv.reader(io.StringIO(text)):
        whid, pin = int(row[0]), int(row[1])
        vals = [None if v == "" else v for v in row[2:]]
        lanes[(whid, pin)] = dict(zip(LANES_KEYS, vals))
    return lanes


WEIGHT_IS_GRAMS = False   # bc_sales_export weights are already in kg

# ---- pricing.py (inlined) ---------------------------------------------
"""Per-carrier pricing engine implemented from the B2C Logistics Commercials sheets."""




CARRIER_BILLING_NAME = {
    "delhivery": "delhivery",
    "bluedart": "bluedart plus",
    "dtdc": "dtdc",
    "ekart": "ekart",
    "shadowfax": "shadowfax",
    "amazon": None,
    "elastic": None,
}


def resolve_zones(carrier_id, zone, data):
    """Returns (system_zone, final_zone) for a carrier zone using the
    Billing Zone Mapping + Actual Zone Name sheets."""
    if not zone:
        return None, None
    billing = data.get("billing_zone_mapping", {})
    actual = data.get("actual_zone_name", {})
    system = None
    key = CARRIER_BILLING_NAME.get(carrier_id)
    if key and key in billing:
        table = billing[key]
        system = table.get(zone)
        if system is None:
            for k, v in table.items():
                if k.lower() == zone.lower():
                    system = v
                    break
    final = actual.get(system) if system else None
    if final is None:
        final = actual.get(zone)
        if final is None:
            for k, v in actual.items():
                if k.lower() == zone.lower():
                    final = v
                    break
    return (system, final) if (system or final) else (None, None)


def r2(x):
    return round(float(x) + 1e-9, 2)


def _grams(weight_kg):
    try:
        return max(0, int(round(float(weight_kg) * 1000)))
    except (TypeError, ValueError):
        return 0


# ---------------------------------------------------------------------------
# Delhivery Surface (W.E.F 01-02-2024)
# ---------------------------------------------------------------------------
def price_delhivery(zone, weight_kg, movement, vol_tier, params):
    movement = (movement or "Fwd").upper()
    if zone == "B_SPL":
        if movement == "DTO":
            return None, "B_SPL has no DTO rate on the card"
        if movement == "RTO":
            return 0.0, "RTO at Rs 0 (included)"
        return params["b_spl"], "Guwahati B_SPL special: Rs 42 / shipment"

    if movement == "RTO":
        # RTO row on the surface card is Rs 0 for all zones
        return 0.0, f"RTO at Rs 0 (included), zone {zone}"

    if movement == "DTO":
        # DTO rates are printed explicitly (independent of the X/Y volume slabs)
        b500 = params["dto"]["base_500"].get(zone)
        a500 = params["dto"]["addl_500"].get(zone)
        if b500 is None or a500 is None:
            return None, f"No DTO rate for zone {zone!r}"
        grams = _grams(weight_kg)
        extra = max(0, grams - 500)
        n_500 = math.ceil(extra / 500.0) if extra > 0 else 0
        total = b500 + n_500 * a500
        return r2(total), f"DTO first 500g Rs {b500} + {n_500}x Rs {a500}/500g"

    # Fwd: flat rate per zone; A/B use X/Y which depend on the monthly volume slab.
    xy = params["xy"].get(vol_tier, params["xy"]["1-3 Lakh"])
    base = params["base_forward"].get(zone)
    if base is None:
        return None, f"No rate for zone {zone!r}"
    if base in ("X", "Y"):
        xy_val = xy.get(base)
        if xy_val is None:
            return None, (
                f"Rate for zone {zone} ({base}) at vol slab {vol_tier} is "
                f"'Existing Rate Card, Table B' which is not printed in the workbook "
                f"- choose a volume slab of 1-3 Lakh or >=3 Lakh to quote"
            )
        base = xy_val
    return r2(base), f"Flat forward Rs {base} (zone {zone}, vol slab {vol_tier}); additional slabs Rs 0"


# ---------------------------------------------------------------------------
# Blue Dart Dart Plus
# ---------------------------------------------------------------------------
def price_bluedart(zone, weight_kg, movement, vol_tier, params):
    movement = (movement or "Fwd").upper()
    rate_zone = params["master_to_rate"].get(zone, zone)
    if rate_zone not in params["first_1kg"]:
        return None, f"No Blue Dart rate for zone {zone!r}"
    base = params["first_1kg"][rate_zone]
    addl = params["addl_500"][rate_zone]
    grams = max(1000, _grams(weight_kg))
    n_500 = math.ceil(max(0, grams - 1000) / 500.0)
    fwd = base + n_500 * addl
    if movement == "RTO":
        fwd = fwd * params["rto_factor"]
        rate_label = f"RTO (70% of forward) zone {rate_zone}"
    else:
        rate_label = f"Forward zone {rate_zone}"
    disc = params["vol_discount"].get(vol_tier, 0.0)
    total = fwd * (1 - disc)
    return r2(total), (
        f"{rate_label}: Rs {base} first 1kg + {n_500}x Rs {addl}/500g"
        f"{' - ' + str(disc * 100).rstrip('0').rstrip('.') + '% vol disc' if disc else ''}"
    )


# ---------------------------------------------------------------------------
# DTDC (w.e.f 21-May-25)
# ---------------------------------------------------------------------------
def price_dtdc(zone, weight_kg, movement, vol_tier, params, whid=None, pin=None):
    """DTDC: Rs X per shipment for the first 5000g, then Rs addl per additional
    1000g (billed per started 1000g slab above 5000g).

    Weight-aware and 0kg-safe: 0-5000g -> the flat first-5000g rate; above that
    ceil((grams-5000)/1000) additional slabs are charged.

    Siliguri DS special (W.E.F Feb 2026): for destination pins in the Siliguri
    region (prefix 734) the DTDC QUIK & SDD rate is Rs 40 per shipment
    (first 5000g) instead of the base first-5000g rate.
    """
    first = params["first_5000g"]
    addl = params["addl_1000g"]
    special = params.get("siliguri") or {}
    rate_label = "DTDC"
    if pin is not None:
        try:
            s = str(int(pin))
            if len(s) == 6 and int(s[:3]) in (special.get("pin_prefixes") or []):
                first = special["rate"]
                rate_label = f"DTDC {special['label']}"
        except (TypeError, ValueError):
            pass
    grams = _grams(weight_kg)
    n_1000 = 0
    if grams > 5000:
        n_1000 = math.ceil((grams - 5000) / 1000.0)
    total = first + n_1000 * addl
    detail = f"{rate_label}: Rs {first} first 5000g"
    if n_1000:
        detail += f" + {n_1000}x Rs {addl}/additional 1000g (billed {grams} g)"
    return r2(total), detail


# ---------------------------------------------------------------------------
# Ekart
# ---------------------------------------------------------------------------
def price_ekart(zone, weight_kg, movement, vol_tier, params):
    plan = params["vol_discount"].get(vol_tier) or params["vol_discount"]["Base rates (Rs 41)"]
    first, addl = plan["first_5kg"], plan["addl_500"]
    grams = _grams(weight_kg)
    if grams <= 5000:
        return r2(first), f"0-5kg flat Rs {first} (incl fwd/COD/RTO){'  [' + vol_tier + ']' if vol_tier else ''}"
    n_500 = math.ceil((grams - 5000) / 500.0)
    total = first + n_500 * addl
    return r2(total), (
        f"Rs {first} (0-5kg) + {n_500}x Rs {addl}/500g thereafter"
        f"{'  [' + vol_tier + ']' if vol_tier else ''}"
    )


# ---------------------------------------------------------------------------
# Shadowfax (W.E.F 01-06-2025)
# ---------------------------------------------------------------------------
def price_shadowfax(zone, weight_kg, movement, vol_tier, params):
    key = None
    for k in params["rates"]:
        if k.lower() == (zone or "").lower():
            key = k
            break
    if key is None:
        return None, f"No Shadowfax rate for zone {zone!r}"
    high = vol_tier == ">=4L"
    rate = params["rates"][key][1 if high else 0]
    tier_label = ">=4L vol" if high else "<4L vol"
    return r2(rate), f"Flat Rs {rate} / shipment ({key}, {tier_label})"


def price_shadowfax_rvp(zone, params):
    """Shadowfax 'RVP with QC' (W.E.F 01-04-2025) — reverse pickup product.

    CPS per RVP category (Local/Regional/Metro/ROI/SZ) plus a flat QC fee of
    Rs 15 per shipment (pass or fail). Zone categories are derived from the
    zone master's Shadowfax forward zone via params['rvp']['zone_map'].
    Liability terms are informational only (not a charge).
    """
    rvp = params.get("rvp") or {}
    zmap = rvp.get("zone_map") or {}
    key = None
    for k in zmap:
        if k.lower() == (zone or "").lower():
            key = k
            break
    if key is None:
        return None, f"No RVP (reverse pickup) rate for Shadowfax zone {zone!r}"
    cat = zmap[key]
    cps = rvp.get("cps", {}).get(cat)
    if cps is None:
        return None, f"No RVP CPS for zone {cat!r}"
    qc = rvp.get("qc", 0.0)
    total = float(cps) + float(qc)
    detail = f"RVP with QC (W.E.F 01-04-2025): CPS Rs {cps} ({cat}) + QC Rs {qc} = Rs {r2(total)}"
    if rvp.get("liability_note"):
        detail += "; " + rvp["liability_note"]
    return r2(total), detail


# ---------------------------------------------------------------------------
# Amazon CPS
# ---------------------------------------------------------------------------
def price_amazon(zone, weight_kg, movement, vol_tier, params):
    cps = params["cps"].get(vol_tier, params["cps"]["<2 Lakh"])
    disc = params["disc"].get(vol_tier, 0.0)
    grams = _grams(weight_kg)
    # "Additional INR 15/Kg for additional 1kg above 2kg" -> billed per full kg above 2 kg.
    chargeable_kg = max(params["base_kg_inclusive"], math.ceil(grams / 1000.0))
    extra_kg = chargeable_kg - params["base_kg_inclusive"]
    addl_rate = params["addl_per_kg"] * (1 - disc)
    total = cps + addl_rate * extra_kg
    note = f"CPS Rs {cps} ({vol_tier})" + (
        f" + {extra_kg}kg x Rs {addl_rate:.2f}" if extra_kg > 0 else ""
    )
    return r2(total), note


# ---------------------------------------------------------------------------
# Elastic Run
# W.E.F 01-07-2025: SDD (local) Rs 37 / delivered order, WH 2, 4, 10, 12, 28.
# W.E.F 20-02-2026: NDD - Regional Rs 40 / delivered order (no return freight,
#                   bill on delivered shipments only).
# The pre-2025 flat Rs 33/32/31 volume scheme is retired. Elastic Run has no
# lane column in the zone master, so local vs regional is inferred from the
# destination pin prefix against the warehouse SDD metro.
# ---------------------------------------------------------------------------
def price_elastic(zone, weight_kg, movement, vol_tier, params, whid, pin=None, service="standard"):
    sdd_whs = params.get("wh_sdd_37_ids") or []
    metro = params.get("metro_prefixes") or {}
    whid = int(whid)

    if service == "sdd":
        if whid not in sdd_whs:
            return None, (
                f"No Elastic Run SDD (local) rate for WH {whid}"
                f" (SDD WHs: {', '.join(map(str, sdd_whs))})"
            )
        return r2(params["sdd_rate"]), (
            f"SDD (local) Rs {params['sdd_rate']} / delivered order "
            f"(W.E.F 01-07-2025, WH {whid})"
        )

    if service == "ndd_regional":
        return r2(params["ndd_regional"]), (
            f"NDD - Regional Rs {params['ndd_regional']} / delivered order "
            "(W.E.F 20-02-2026); no return freight, bill on delivered only"
        )

    # Default: auto local/regional from the destination pin (WH-based coverage).
    if whid not in sdd_whs:
        return None, (
            f"Elastic Run has no rate scheme for WH {whid}"
            f" (SDD WHs: {', '.join(map(str, sdd_whs))})"
        )
    local = False
    rates = metro.get(whid) or metro.get(str(whid))
    if rates and pin:
        try:
            local = int(str(int(pin))[:3]) in rates
        except (TypeError, ValueError):
            local = False
    if local:
        return r2(params["sdd_rate"]), (
            f"SDD (local) Rs {params['sdd_rate']} / delivered order "
            f"(W.E.F 01-07-2025, WH {whid}, dest {pin} in SDD metro)"
        )
    return r2(params["ndd_regional"]), (
        f"NDD - Regional Rs {params['ndd_regional']} / delivered order "
        f"(W.E.F 20-02-2026, WH {whid}, dest {pin} outside SDD metro); "
        "no return freight, bill on delivered only"
    )


PRICERS = {
    "delhivery": price_delhivery,
    "bluedart": price_bluedart,
    "dtdc": price_dtdc,
    "ekart": price_ekart,
    "shadowfax": price_shadowfax,
    "amazon": price_amazon,
    "elastic": price_elastic,
}


def quote_carrier(carrier, zone, weight_kg, movement, opts, data):
    """Compute cost for one carrier. `zone` is the carrier zone (None = not served)."""
    params = data["price_cards"][carrier["id"]]
    movement = (movement or "Fwd").upper()
    base = {
        "id": carrier["id"],
        "name": carrier["name"],
        "master_zone": zone,
        "cost": None,
        "served": False,
        "details": "",
    }

    # A carrier with no lane zone is simply not served on this lane.
    if not zone and carrier["id"] != "elastic":
        base["system_zone"] = base["final_zone"] = None
        base["rate_basis"] = "Not served on this lane"
        return base

    # Only quote movements that are actually on the carrier's commercial card.
    supported = [str(m).upper() for m in (params.get("movements") or ["Fwd"])]
    if movement not in supported:
        base["system_zone"], base["final_zone"] = resolve_zones(carrier["id"], zone, data)
        base["rate_basis"] = (
            f"{movement} not quoted on the {carrier['name']} card"
            f" (card covers: {', '.join(supported).lower()})"
        )
        return base
    fn = PRICERS[carrier["id"]]
    vol_tier = opts.get("volume", {}).get(carrier["id"])
    for label in ("xy", "vol_discount", "cps", "vol_rates"):
        params_vol = params.get(label)
        if params_vol and vol_tier is None:
            vol_tier = next(iter(params_vol), None)
            break
    if carrier["id"] == "elastic":
        cost, detail = fn(zone, weight_kg, movement, vol_tier, params,
                          whid=opts.get("whid"), pin=opts.get("pin"),
                          service=opts.get("elastic_service", "standard"))
    elif carrier["id"] == "dtdc":
        cost, detail = fn(zone, weight_kg, movement, vol_tier, params,
                          whid=opts.get("whid"), pin=opts.get("pin"))
    else:
        cost, detail = fn(zone, weight_kg, movement, vol_tier, params)
    system_zone, final_zone = resolve_zones(carrier["id"], zone, data)
    base.update({
        "system_zone": system_zone,
        "final_zone": final_zone,
        "served": cost is not None,
        "cost": cost,
        "rate_basis": detail if detail else ("Not served on this lane" if cost is None else None),
    })
    return base

# ---- cps_compute logic (inlined) ---------------------------------------
"""Per-shipment freight (CPS) calculation for the B2C shipment export.

Appends a computed freight cost to every row of the BigQuery shipment
DataFrame using the exact same rate-card engine as the B2C cost-calculator
web app (see py + data/lanes.db + data/b2c_data.json in this
project).

Drop this file next to py and the data/ folder on the server, then:

    from cps_compute import compute_cps
    df = compute_cps(df)

Added columns
-------------
whid_resolved          integer rate-card warehouse id matched for the row
carrier_id_mapped      rate-card carrier id matched for the row
movement_used          "Fwd" / "RTO" (auto-detected)
chargeable_weight_kg   billing weight = max(weight, vol_weight), in kg
calculated_freight     Rs per shipment per the rate card (None if not quotable)
carrier_zone_used      zone string used for the rate lookup
freight_rate_basis     verbose basis (the "rate_basis" string from py)
freight_status         ok / machine-readable reason when calculated_freight is None

Defaults used (same as the web app's out-of-the-box behaviour):
* movement -> Fwd (RTO auto-detected from status columns)
* volume tier -> each carrier's lowest tier (no monthly-volume discounts)
* elastic service -> standard == auto (local Rs 37 / regional Rs 40, only
  for WH 2/4/10/12/28; other warehouses are not served -- matching the app)
* Delhivery <1 Lakh forward is intentionally NOT quoted on A/B lanes
  (C1..F etc. still quote) -- identical to the app.
"""



import json
import os
import re

from functools import lru_cache

import pandas as pd



THIS_DIR = os.path.dirname(os.path.abspath(__file__))
DATA_DIR = os.path.join(THIS_DIR, "data")
LANES_DB = os.path.join(DATA_DIR, "lanes.db")
B2C_JSON = os.path.join(DATA_DIR, "b2c_data.json")

# Purplle stores shipment weights in grams (0.5 kg = 500).
# Set to False if the export already provides charges in kg.


# carrier_id -> lanes.db column holding that carrier's zone (elastic is WH-based).
LANE_COLUMN = {
    "delhivery": "delhivery",
    "bluedart": "bluedart_plus",
    "dtdc": "dtdc",
    "ekart": "ekart",
    "shadowfax": "shadowfax",
    "amazon": "amazon",
    "elastic": None,
}

# Purplle shipment carrier-name fragments -> rate-card carrier id.
# Matched on lowercased, non-alphanumeric-stripped text (substring).
CARRIER_ALIASES = (
    ("ekart", "ekart"),
    ("delhivery", "delhivery"),
    ("blue dart", "bluedart"),
    ("dart plus", "bluedart"),
    ("dtdc", "dtdc"),
    ("shadowfax", "shadowfax"),
    ("amazon", "amazon"),
    ("elastic", "elastic"),
)

# Lowest tier per carrier = no monthly-volume discount (matches app defaults).
# Only carriers whose pricing actually consumes a volume tier are listed;
# others are priced at their base rate automatically by py.
DEFAULT_VOLUME = {
    "delhivery": "<1 Lakh",
    "bluedart": "Up to 1,50,000",
    "ekart": "Base rates (Rs 41)",
    "amazon": "<2 Lakh",
}

# Manual override for warehouse matching when the export's warehouse name does
# not resolve. Format: {"warehouse_name as it appears in the CSV": whid}
WH_NAME_MAP = {}


def _norm(value):
    """Lowercase + strip to digits/letters for fuzzy matching."""
    return re.sub(r"[^a-z0-9]", "", str(value or "").lower())




def _kg(value):
    """Convert the export's weight to kg. None-safe; ignores non-positive/NaN."""
    try:
        value = float(value)
    except (TypeError, ValueError):
        return None
    if value != value or value <= 0:  # NaN guard
        return None
    return value / 1000.0 if WEIGHT_IS_GRAMS else value


def _clean_pin(value):
    try:
        text = str(value).strip()
        if not text:
            return None
        return int(text.replace(",", "").split(".")[0])
    except (TypeError, ValueError):
        return None


def carrier_id_for(raw_name):
    """Map the export's carrier_name to a rate-card carrier id (or None)."""
    n = _norm(raw_name)
    if not n:
        return None
    for key, cid in CARRIER_ALIASES:
        if _norm(key) in n:
            return cid
    return None


def _build_wh_index():
    """Index the rate-card warehouses by id / origin pin / normalized name."""
    by_id, by_pin, by_name = {}, {}, {}
    for w in _data()["warehouses"]:
        by_id[int(w["whid"])] = w["whid"]
        if w.get("origin_pin"):
            by_pin[int(w["origin_pin"])] = w["whid"]
            by_name[_norm(w["origin_pin"])] = w["whid"]
        for key in ("code", "address"):
            if w.get(key):
                by_name[_norm(w[key])] = w["whid"]
    return by_id, by_pin, by_name


def resolve_whid(row, wh_by_id, wh_by_pin, wh_by_name):
    """Return (rate-card whid, how-matched) for a shipment row."""
    raw_id = row.get("warehouse_id")
    try:
        wid = int(raw_id)
        if wid in wh_by_id:
            return wid, "by id"
    except (TypeError, ValueError):
        pass

    name = _norm(row.get("warehouse_name"))
    for key, whid in WH_NAME_MAP.items():
        if _norm(key) and (_norm(key) in name or name in _norm(key)):
            return whid, "manual override"

    if name:
        if name in wh_by_name:
            return wh_by_name[name], "by name"
        for key, whid in wh_by_name.items():  # partial containment match
            if key and (name in key or key in name):
                return whid, "by name (partial)"

    pin = _clean_pin(row.get("postal_code"))
    if pin and pin in wh_by_pin:
        return wh_by_pin[pin], "by origin pin"

    return None, f"unmatched whid={raw_id!r} name={row.get('warehouse_name')!r}"


def _movement_for(row):
    sec = str(row.get("latest_secondary_status") or "").lower()
    st = str(row.get("shipment_status") or "").lower()
    if "rto" in sec or "rto" in st or "return" in st:
        return "RTO"
    rto_dt = row.get("rto_marked_on")
    if rto_dt is not None and str(rto_dt) not in ("", "NaT", "nan") and not pd.isna(rto_dt):
        return "RTO"
    return "Fwd"




def zones_for(whid, pin):
    return _load_lanes().get((whid, pin)) or {}


def freight_for_row(carrier_id, whid, pin, weight_kg, movement):
    """Compute the rate-card freight for one shipment.

    Returns (cost, zone, rate_basis, status). cost is None when the shipment
    cannot be priced; status gives a machine-readable reason.
    """
    if carrier_id is None:
        return None, None, "carrier not modelled", "no carrier"
    zone = None
    if carrier_id != "elastic":
        zones = zones_for(whid, pin)
        col = LANE_COLUMN[carrier_id]
        if zones.get(col) is None:
            if not zones:
                return None, None, "lane (whid, pin) not in zone master", "no lane"
            return None, None, "carrier not served on this lane", "no zone"
        zone = zones[col]
    carrier = {"id": carrier_id, "name": carrier_id}
    opts = {"whid": whid, "pin": pin, "volume": dict(DEFAULT_VOLUME), "elastic_service": "standard"}
    try:
        res = quote_carrier(carrier, zone, weight_kg, movement, opts, _data())
    except Exception as exc:  # defensive: never break the whole export
        return None, zone, f"quote error: {exc}", "quote error"
    if res.get("cost") is None:
        return None, zone, res.get("rate_basis") or "not served", "no quote"
    return round(float(res["cost"]), 2), zone, res.get("rate_basis") or "", "ok"


def compute_cps(df):
    """Append the calculated-freight columns to the shipment DataFrame."""
    df = df.copy()
    wh_by_id, wh_by_pin, wh_by_name = _build_wh_index()

    whids, how_matched, cids, movements = [], [], [], []
    chargeable, freights, zones_used, bases, statuses = [], [], [], [], []

    for _, row in df.iterrows():
        whid, how = resolve_whid(row, wh_by_id, wh_by_pin, wh_by_name)
        whids.append(whid)
        how_matched.append(how)

        carrier_name = row.get("carrier_name")
        if not carrier_name:
            carrier_name = row.get("picklist_carrier_name")
        cid = carrier_id_for(carrier_name)
        cids.append(cid)

        mv = _movement_for(row)
        movements.append(mv)

        weight_kg = _kg(row.get("weight"))
        vol_kg = _kg(row.get("vol_weight"))
        if weight_kg is None and vol_kg is None:
            cw = None
        elif weight_kg is None:
            cw = vol_kg
        elif vol_kg is None:
            cw = weight_kg
        else:
            cw = max(weight_kg, vol_kg)  # billing weight
        chargeable.append(cw)

        pin = _clean_pin(row.get("ship_postal_code")) or _clean_pin(row.get("pincode"))
        if whid is None or cw is None or pin is None:
            freights.append(None)
            zones_used.append(None)
            if whid is None:
                bases.append("warehouse not resolved"); statuses.append("no wh")
            elif cw is None:
                bases.append("no valid weight/vol_weight"); statuses.append("no weight")
            else:
                bases.append("no valid destination pincode"); statuses.append("no pin")
            continue

        cost, zone, basis, status = freight_for_row(cid, whid, pin, cw, mv)
        freights.append(cost)
        zones_used.append(zone)
        bases.append(basis)
        statuses.append(status)

    df["whid_resolved"] = whids
    df["wh_matched_by"] = how_matched
    df["carrier_id_mapped"] = cids
    df["movement_used"] = movements
    df["chargeable_weight_kg"] = chargeable
    df["calculated_freight"] = freights
    df["carrier_zone_used"] = zones_used
    df["freight_rate_basis"] = bases
    df["freight_status"] = statuses
    return df


def freight_summary(df):
    """One-line + per-status counts so the driver can log a summary."""
    ok = df["calculated_freight"].notna()
    text = [
        f"[CPS] freight computed for {ok.mean()*100:.1f}% of rows",
        f"(mean Rs {df.loc[ok, 'calculated_freight'].mean():,.2f})",
    ]
    for status, count in df["freight_status"].value_counts().items():
        text.append(f"{status}: {count:,}")
    return " | ".join(text)




